sealed class MobileException: kotlin.Exception() {
    
    class Failure(
        
        val `reason`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<MobileException> {
        override fun lift(error_buf: RustBuffer.ByValue): MobileException = FfiConverterTypeMobileError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeMobileError : FfiConverterRustBuffer<MobileException> {
    override fun read(buf: ByteBuffer): MobileException {
        

        return when(buf.getInt()) {
            1 -> MobileException.Failure(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: MobileException): ULong {
        return when(value) {
            is MobileException.Failure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: MobileException, buf: ByteBuffer) {
        when(value) {
            is MobileException.Failure -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * The shared sync state, so Android and iOS render one state machine.
 */

enum class SyncStateInfo {
    
    IDLE,
    DIRTY,
    SYNCING,
    CONFLICT,
    ERROR;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeSyncStateInfo: FfiConverterRustBuffer<SyncStateInfo> {
    override fun read(buf: ByteBuffer) = try {
        SyncStateInfo.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: SyncStateInfo) = 4UL

    override fun write(value: SyncStateInfo, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





